mapper.select:
select event_type as "eventType", source_name as "sourceName", programme as "programme",
       daily_cap_points as "dailyCapPoints", status as "status"
from points_award_cap where event_type = #{eventType}

select programme as "programme", programme_name as "programmeName",
       monthly_budget_points as "monthlyBudgetPoints", status as "status"
from points_programme_budget where programme = #{programme}

select coalesce(sum(change_points), 0) from ums_member_points_detail
where member_id = #{memberId} and event_type = #{eventType} and change_type = 1
  and (del_flag is null or del_flag = 0) and create_time >= #{since}

mapper.update:
update points_budget_usage
set issued_points = issued_points + #{points}, update_time = #{now}
where programme = #{programme} and period = #{period}
and issued_points + #{points} <= #{budget}

update points_award_cap
set daily_cap_points = #{dailyCapPoints}, status = #{status}, update_by = #{updateBy}, update_time = #{now}
where event_type = #{eventType}

update points_programme_budget
set monthly_budget_points = #{monthlyBudgetPoints}, status = #{status}, update_by = #{updateBy}, update_time = #{now}
where programme = #{programme}

mapper.select:
select coalesce(sum(abs(change_points)), 0) from ums_member_points_detail
where change_type = #{changeType} and (del_flag is null or del_flag = 0)
  and create_time >= #{from} and create_time < #{to}
